# The error says "invalid type: string, expected str or bytes" 
# which means the response should be a CBOR string/bytes

# Let me test what the correct response format is by capturing more data

cat > /tmp/test_server4.py << 'EOF'
import socket
import os
import struct

sock_path = '/tmp/pueue_test/pueue.sock'
if os.path.exists(sock_path):
    os.unlink(sock_path)

def decode_cbor(data):
    pos = 0
    def read_uint(additional):
        nonlocal pos
        if additional < 24: return additional
        elif additional == 24: v = data[pos]; pos += 1; return v
        elif additional == 25: v = int.from_bytes(data[pos:pos+2], 'big'); pos += 2; return v
        elif additional == 26: v = int.from_bytes(data[pos:pos+4], 'big'); pos += 4; return v
        elif additional == 27: v = int.from_bytes(data[pos:pos+8], 'big'); pos += 8; return v
    def decode():
        nonlocal pos
        b = data[pos]; pos += 1
        major = b >> 5; additional = b & 0x1f
        if major == 0: return read_uint(additional)
        elif major == 1: return -1 - read_uint(additional)
        elif major == 2: n = read_uint(additional); v = data[pos:pos+n]; pos += n; return v
        elif major == 3: n = read_uint(additional); v = data[pos:pos+n].decode('utf-8'); pos += n; return v
        elif major == 4: n = read_uint(additional); return [decode() for _ in range(n)]
        elif major == 5: n = read_uint(additional); return {decode(): decode() for _ in range(n)}
        elif major == 7:
            if additional == 20: return False
            elif additional == 21: return True
            elif additional == 22: return None
    return decode()

def encode_cbor(obj):
    if obj is None: return bytes([0xf6])
    elif obj is True: return bytes([0xf5])
    elif obj is False: return bytes([0xf4])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24: return bytes([obj])
            elif obj < 256: return bytes([0x18, obj])
            elif obj < 65536: return bytes([0x19]) + obj.to_bytes(2, 'big')
            else: return bytes([0x1a]) + obj.to_bytes(4, 'big')
        else:
            n = -1 - obj
            if n < 24: return bytes([0x20 | n])
            elif n < 256: return bytes([0x38, n])
    elif isinstance(obj, str):
        b = obj.encode('utf-8')
        n = len(b)
        if n < 24: return bytes([0x60 | n]) + b
        elif n < 256: return bytes([0x78, n]) + b
        else: return bytes([0x79]) + n.to_bytes(2, 'big') + b
    elif isinstance(obj, bytes):
        n = len(obj)
        if n < 24: return bytes([0x40 | n]) + obj
    elif isinstance(obj, list):
        n = len(obj)
        if n < 24: header = bytes([0x80 | n])
        else: header = bytes([0x98, n])
        return header + b''.join(encode_cbor(x) for x in obj)
    elif isinstance(obj, dict):
        n = len(obj)
        if n < 24: header = bytes([0xa0 | n])
        else: header = bytes([0xb8, n])
        result = header
        for k, v in obj.items():
            result += encode_cbor(k) + encode_cbor(v)
        return result

def read_message(conn):
    header = b""
    while len(header) < 8:
        chunk = conn.recv(8 - len(header))
        if not chunk: raise Exception("Connection closed")
        header += chunk
    length = struct.unpack('>Q', header)[0]
    body = b""
    while len(body) < length:
        chunk = conn.recv(length - len(body))
        if not chunk: raise Exception("Connection closed")
        body += chunk
    return body

def send_message(conn, data):
    if isinstance(data, (dict, list, str, int, bool, type(None))):
        data = encode_cbor(data)
    header = struct.pack('>Q', len(data))
    conn.sendall(header + data)

server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
server.bind(sock_path)
server.listen(5)
server.settimeout(15)
print("Listening...", flush=True)

commands_to_try = ['status', 'group', 'add', 'log']
i = 0
try:
    while i < 10:
        try:
            conn, _ = server.accept()
            print(f"\n=== Connection {i} ===", flush=True)
            conn.settimeout(5)

            secret = read_message(conn)
            print(f"Secret: {secret!r}", flush=True)
            send_message(conn, "4.0.4")

            msg = read_message(conn)
            decoded = decode_cbor(msg)
            print(f"Request: {decoded}", flush=True)

            # Send a proper response
            # For status: {"StatusResponse": {"tasks": {}, "groups": {}}}
            if decoded == "Status":
                resp = {"StatusResponse": {"tasks": {}, "groups": {"default": {"status": "Running", "parallel_tasks": 1}}}}
            elif isinstance(decoded, dict) and "Group" in decoded:
                resp = {"GroupResponse": {"groups": {"default": {"status": "Running", "parallel_tasks": 1}}}}
            else:
                resp = {"SimpleSuccess": "Task added successfully."}

            print(f"Sending response: {resp}", flush=True)
            send_message(conn, resp)

            # Try to read any more messages
            try:
                while True:
                    msg2 = read_message(conn)
                    print(f"Additional msg: {decode_cbor(msg2)}", flush=True)
            except:
                pass

            conn.close()
            i += 1
        except socket.timeout:
            break
except Exception as e:
    print(f"Server error: {e}", flush=True)
    import traceback; traceback.print_exc()
finally:
    server.close()
    if os.path.exists(sock_path):
        os.unlink(sock_path)
EOF

