def encode_cbor(obj):
    if obj is None: return bytes([0xf6])
    elif obj is True: return bytes([0xf5])
    elif obj is False: return bytes([0xf4])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24: return bytes([obj])
            elif obj < 256: return bytes([0x18, obj])
            elif obj < 65536: return bytes([0x19]) + obj.to_bytes(2, 'big')
            else: return bytes([0x1a]) + obj.to_bytes(4, 'big')
    elif isinstance(obj, str):
        b = obj.encode('utf-8')
        n = len(b)
        if n < 24: return bytes([0x60 | n]) + b
        elif n < 256: return bytes([0x78, n]) + b
        else: return bytes([0x79]) + n.to_bytes(2, 'big') + b
    elif isinstance(obj, list):
        n = len(obj)
        if n < 24: header = bytes([0x80 | n])
        else: header = bytes([0x98, n])
        return header + b''.join(encode_cbor(x) for x in obj)
    elif isinstance(obj, dict):
        n = len(obj)
        if n < 24: header = bytes([0xa0 | n])
        else: header = bytes([0xb8, n])
        result = header
        for k, v in obj.items():
            result += encode_cbor(k) + encode_cbor(v)
        return result

def read_message(conn):
    header = b""
    while len(header) < 8:
        chunk = conn.recv(8 - len(header))
        if not chunk: raise Exception("Connection closed")
        header += chunk
    length = struct.unpack('>Q', header)[0]
    body = b""
    while len(body) < length:
        chunk = conn.recv(length - len(body))
        if not chunk: raise Exception("Connection closed")
        body += chunk
    return body

def send_raw(conn, data):
    if isinstance(data, str): data = data.encode('utf-8')
    conn.sendall(struct.pack('>Q', len(data)) + data)

def send_cbor(conn, obj):
    send_raw(conn, encode_cbor(obj))

