def enc(obj):
    if obj is None: return bytes([0xf6])
    elif obj is True: return bytes([0xf5])
    elif obj is False: return bytes([0xf4])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24: return bytes([obj])
            elif obj < 256: return bytes([0x18, obj])
            elif obj < 65536: return bytes([0x19]) + obj.to_bytes(2, 'big')
            else: return bytes([0x1a]) + obj.to_bytes(4, 'big')
