#!/usr/bin/env python3
"""
Pueue client implementation - reimplementation of pueue 4.0.4
"""
import sys
import os
import socket
import struct
import json
import re
import stat
import time
import hashlib
import argparse
import shutil
from datetime import datetime, timezone
from typing import Optional, List, Dict, Any, Tuple

VERSION = "4.0.4"
PROTOCOL_VERSION = "0.31.1"

# ANSI colors
class Color:
    RED = '\033[91m'
    GREEN = '\033[92m'
    YELLOW = '\033[93m'
    BLUE = '\033[94m'
    MAGENTA = '\033[95m'
    CYAN = '\033[36m'
    WHITE = '\033[97m'
    DIM = '\033[2m'
    BOLD = '\033[1m'
    RESET = '\033[0m'

_use_color = True  # Will be set based on --color flag

def colored(text, *colors):
    if not _use_color:
        return text
    codes = ''.join(colors)
    return f"{codes}{text}{Color.RESET}"

def error_msg(msg):
    """Print error in pueue style"""
    if _use_color:
        sys.stderr.write(f"Error: \n   0: {Color.RED}{msg}{Color.RESET}\n\n")
    else:
        sys.stderr.write(f"Error: \n   0: {msg}\n\n")

def error_msg_chain(msgs):
    """Print chained error in pueue style"""
    if _use_color:
        sys.stderr.write("Error: \n")
        for i, msg in enumerate(msgs):
            sys.stderr.write(f"   {i}: {Color.RED}{msg}{Color.RESET}\n")
        sys.stderr.write("\n")
    else:
        sys.stderr.write("Error: \n")
        for i, msg in enumerate(msgs):
            sys.stderr.write(f"   {i}: {msg}\n")
        sys.stderr.write("\n")

# ============ CBOR ENCODING/DECODING ============

def cbor_encode(obj):
    """Encode Python object to CBOR bytes"""
    if obj is None:
        return bytes([0xf6])
    elif obj is True:
        return bytes([0xf5])
    elif obj is False:
        return bytes([0xf4])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24: return bytes([obj])
            elif obj < 256: return bytes([0x18, obj])
            elif obj < 65536: return bytes([0x19]) + obj.to_bytes(2, 'big')
            elif obj < 2**32: return bytes([0x1a]) + obj.to_bytes(4, 'big')
            else: return bytes([0x1b]) + obj.to_bytes(8, 'big')
        else:
            n = -1 - obj
            if n < 24: return bytes([0x20 | n])
            elif n < 256: return bytes([0x38, n])
            elif n < 65536: return bytes([0x39]) + n.to_bytes(2, 'big')
            else: return bytes([0x3a]) + n.to_bytes(4, 'big')
    elif isinstance(obj, float):
        import struct as st
        return bytes([0xfb]) + st.pack('>d', obj)
    elif isinstance(obj, str):
        b = obj.encode('utf-8')
        n = len(b)
        if n < 24: return bytes([0x60 | n]) + b
        elif n < 256: return bytes([0x78, n]) + b
        elif n < 65536: return bytes([0x79]) + n.to_bytes(2, 'big') + b
        else: return bytes([0x7a]) + n.to_bytes(4, 'big') + b
    elif isinstance(obj, bytes):
        n = len(obj)
        if n < 24: return bytes([0x40 | n]) + obj
        elif n < 256: return bytes([0x58, n]) + obj
        elif n < 65536: return bytes([0x59]) + n.to_bytes(2, 'big') + obj
        else: return bytes([0x5a]) + n.to_bytes(4, 'big') + obj
    elif isinstance(obj, (list, tuple)):
        n = len(obj)
        if n < 24: header = bytes([0x80 | n])
        elif n < 256: header = bytes([0x98, n])
        else: header = bytes([0x99]) + n.to_bytes(2, 'big')
        return header + b''.join(cbor_encode(x) for x in obj)
    elif isinstance(obj, dict):
        n = len(obj)
        if n < 24: header = bytes([0xa0 | n])
        elif n < 256: header = bytes([0xb8, n])
        else: header = bytes([0xb9]) + n.to_bytes(2, 'big')
        result = header
        for k, v in obj.items():
            result += cbor_encode(k) + cbor_encode(v)
        return result
    else:
