    except Exception as e:
        error_msg_chain([
            "Failed to initialize client.",
            "Failed to initialize stream.",
            str(e)
        ])
        sys.exit(1)

    # Send secret
    try:
        send_message(s, secret)
    except Exception as e:
        error_msg_chain(["Failed to initialize client.", str(e)])
        sys.exit(1)

    # Receive version
    try:
