# ============ CBOR ENCODING/DECODING ============

def cbor_encode(obj):
    """Encode Python object to CBOR bytes"""
    if obj is None:
        return bytes([0xf6])
    elif obj is True:
        return bytes([0xf5])
    elif obj is False:
        return bytes([0xf4])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24: return bytes([obj])
            elif obj < 256: return bytes([0x18, obj])
            elif obj < 65536: return bytes([0x19]) + obj.to_bytes(2, 'big')
            elif obj < 2**32: return bytes([0x1a]) + obj.to_bytes(4, 'big')
            else: return bytes([0x1b]) + obj.to_bytes(8, 'big')
        else:
            n = -1 - obj
            if n < 24: return bytes([0x20 | n])
            elif n < 256: return bytes([0x38, n])
            elif n < 65536: return bytes([0x39]) + n.to_bytes(2, 'big')
            else: return bytes([0x3a]) + n.to_bytes(4, 'big')
    elif isinstance(obj, float):
        import struct as st
        return bytes([0xfb]) + st.pack('>d', obj)
    elif isinstance(obj, str):
        b = obj.encode('utf-8')
        n = len(b)
        if n < 24: return bytes([0x60 | n]) + b
        elif n < 256: return bytes([0x78, n]) + b
        elif n < 65536: return bytes([0x79]) + n.to_bytes(2, 'big') + b
        else: return bytes([0x7a]) + n.to_bytes(4, 'big') + b
    elif isinstance(obj, bytes):
        n = len(obj)
        if n < 24: return bytes([0x40 | n]) + obj
        elif n < 256: return bytes([0x58, n]) + obj
        elif n < 65536: return bytes([0x59]) + n.to_bytes(2, 'big') + obj
        else: return bytes([0x5a]) + n.to_bytes(4, 'big') + obj
    elif isinstance(obj, (list, tuple)):
        n = len(obj)
        if n < 24: header = bytes([0x80 | n])
        elif n < 256: header = bytes([0x98, n])
        else: header = bytes([0x99]) + n.to_bytes(2, 'big')
        return header + b''.join(cbor_encode(x) for x in obj)
    elif isinstance(obj, dict):
        n = len(obj)
        if n < 24: header = bytes([0xa0 | n])
        elif n < 256: header = bytes([0xb8, n])
        else: header = bytes([0xb9]) + n.to_bytes(2, 'big')
        result = header
        for k, v in obj.items():
            result += cbor_encode(k) + cbor_encode(v)
        return result
    else:
        raise ValueError(f"Cannot CBOR encode: {type(obj)}: {obj!r}")

def cbor_decode(data, pos=0):
    """Decode CBOR bytes to Python object. Returns (value, new_pos)"""
    if pos >= len(data):
        raise ValueError("Unexpected end of CBOR data")

    b = data[pos]; pos += 1
    major = b >> 5
    additional = b & 0x1f

    def read_uint(additional, pos):
        if additional < 24: return additional, pos
        elif additional == 24:
            return data[pos], pos + 1
        elif additional == 25:
            return int.from_bytes(data[pos:pos+2], 'big'), pos + 2
        elif additional == 26:
            return int.from_bytes(data[pos:pos+4], 'big'), pos + 4
        elif additional == 27:
            return int.from_bytes(data[pos:pos+8], 'big'), pos + 8
        else:
            raise ValueError(f"Unsupported additional: {additional}")

    if major == 0:  # unsigned int
        val, pos = read_uint(additional, pos)
        return val, pos
    elif major == 1:  # negative int
        n, pos = read_uint(additional, pos)
        return -1 - n, pos
    elif major == 2:  # bytes
        n, pos = read_uint(additional, pos)
        return data[pos:pos+n], pos + n
    elif major == 3:  # text
        n, pos = read_uint(additional, pos)
        return data[pos:pos+n].decode('utf-8'), pos + n
    elif major == 4:  # array
        n, pos = read_uint(additional, pos)
        result = []
        for _ in range(n):
            v, pos = cbor_decode(data, pos)
            result.append(v)
        return result, pos
    elif major == 5:  # map
        n, pos = read_uint(additional, pos)
        result = {}
        for _ in range(n):
            k, pos = cbor_decode(data, pos)
            v, pos = cbor_decode(data, pos)
            result[k] = v
        return result, pos
    elif major == 6:  # tag
        _, pos = read_uint(additional, pos)  # skip tag
        return cbor_decode(data, pos)
    elif major == 7:  # special
        if additional == 20: return False, pos
        elif additional == 21: return True, pos
        elif additional == 22: return None, pos
        elif additional == 23: return None, pos  # undefined
        elif additional == 25:  # float16
            import struct as st
            half = int.from_bytes(data[pos:pos+2], 'big')
            pos += 2
            exp = (half >> 10) & 0x1f
            mant = half & 0x3ff
            if exp == 0: val = mant * 2**-24
            elif exp == 31: val = float('inf') if mant == 0 else float('nan')
            else: val = (mant / 1024 + 1) * 2**(exp-15)
            if half >> 15: val = -val
            return val, pos
        elif additional == 26:  # float32
            import struct as st
            val = st.unpack('>f', data[pos:pos+4])[0]
            return val, pos + 4
        elif additional == 27:  # float64
            import struct as st
            val = st.unpack('>d', data[pos:pos+8])[0]
            return val, pos + 8
        else:
            raise ValueError(f"Unsupported special: {additional}")
    else:
        raise ValueError(f"Invalid major type: {major}")

# ============ CONFIG FILE READING ============

def find_config_file():
    """Find pueue config file in standard locations"""
    # Check env var first
    env_path = os.environ.get('PUEUE_CONFIG_PATH')
    if env_path:
        return env_path

    # XDG config dirs
    xdg_config = os.environ.get('XDG_CONFIG_HOME', os.path.expanduser('~/.config'))
    candidates = [
        os.path.join(xdg_config, 'pueue', 'pueue.yml'),
        os.path.join(xdg_config, 'pueue', 'pueue.yaml'),
        os.path.expanduser('~/.config/pueue/pueue.yml'),
        os.path.expanduser('~/.config/pueue/pueue.yaml'),
    ]
    for c in candidates:
        if os.path.exists(c):
            return c
    return None

def simple_yaml_parse(text):
    """Very simple YAML parser for pueue config files"""
    result = {}
    stack = [result]  # stack of current objects
    indent_stack = [-1]
    key_stack = [None]

    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        # Skip comments and empty lines
        stripped = line.lstrip()
        if not stripped or stripped.startswith('#'):
            i += 1
            continue

        # Remove trailing comment
        indent = len(line) - len(stripped)

        # Parse key: value or key:
        if stripped.startswith('- '):
            # List item
            val_str = stripped[2:].strip()
            val = parse_yaml_value(val_str)
            if isinstance(stack[-1], list):
                stack[-1].append(val)
            i += 1
            continue

        if ':' not in stripped:
            i += 1
            continue

        colon_idx = stripped.index(':')
        key = stripped[:colon_idx].strip()
        val_str = stripped[colon_idx+1:].strip()

        # Handle indentation
        while len(indent_stack) > 1 and indent <= indent_stack[-1]:
            indent_stack.pop()
            stack.pop()
            key_stack.pop()

        if val_str == '' or val_str.startswith('#'):
            # Next lines are nested
            indent_stack.append(indent)
            key_stack.append(key)
            # Check if it's a list or dict
            if i + 1 < len(lines):
                next_stripped = lines[i+1].lstrip()
                if next_stripped.startswith('- '):
                    new_obj = []
                else:
                    new_obj = {}
            else:
                new_obj = {}

            if isinstance(stack[-1], dict):
                stack[-1][key] = new_obj
            elif isinstance(stack[-1], list):
                stack[-1].append({key: new_obj})
            stack.append(new_obj)
        else:
            val = parse_yaml_value(val_str)
            if isinstance(stack[-1], dict):
                stack[-1][key] = val

        i += 1

    return result

def parse_yaml_value(s):
    """Parse a YAML scalar value"""
    if not s or s == '~' or s == 'null':
        return None
    if s == 'true' or s == 'True':
        return True
    if s == 'false' or s == 'False':
        return False
    # Remove quotes
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    # Try integer
    try:
        return int(s)
    except ValueError:
        pass
    # Try float
    try:
        return float(s)
    except ValueError:
        pass
    # String
    return s

def load_config(config_path):
    """Load and parse pueue config file"""
    try:
        with open(config_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        error_msg_chain([
            "Failed to read configuration.",
