    except PermissionError:
        error_msg_chain([
            "Failed to read configuration.",
            f'I/O error at path "{config_path}" while opening config file:\nPermission denied (os error 13)'
        ])
        sys.exit(1)

    try:
        config = simple_yaml_parse(content)
    except Exception as e:
        error_msg_chain([
            "Failed to read configuration.",
            f"Failed to parse config file: {e}"
        ])
        sys.exit(1)

    return config

def get_default_config():
    """Get default config values"""
    xdg_data = os.environ.get('XDG_DATA_HOME', os.path.expanduser('~/.local/share'))
    pueue_dir = os.path.join(xdg_data, 'pueue')

    return {
        'shared': {
