def merge_config(base, override):
    """Merge override config into base"""
    result = dict(base)
    for k, v in override.items():
        if isinstance(v, dict) and k in result and isinstance(result[k], dict):
            result[k] = merge_config(result[k], v)
        else:
            result[k] = v
    return result

def get_config(config_path=None):
    """Get the merged config"""
    base = get_default_config()

    if config_path:
        if not os.path.exists(config_path):
            error_msg_chain([
                "Failed to read configuration.",
                f'I/O error at path "{config_path}" while opening config file:\nNo such file or directory (os error 2)'
            ])
            sys.exit(1)
        override = load_config(config_path)
        return merge_config(base, override)

    found = find_config_file()
    if found:
        override = load_config(found)
        return merge_config(base, override)

    return None  # No config found

def get_socket_path(config):
    """Get the unix socket path from config"""
    shared = config.get('shared', {})
    if shared.get('use_unix_socket', True):
        socket_path = shared.get('unix_socket_path')
        if socket_path:
            return socket_path
        pueue_dir = shared.get('pueue_directory', os.path.expanduser('~/.local/share/pueue'))
        return os.path.join(pueue_dir, 'pueue.sock')
    return None

def get_secret_path(config):
    """Get the shared secret file path"""
    shared = config.get('shared', {})
    pueue_dir = shared.get('pueue_directory', os.path.expanduser('~/.local/share/pueue'))
    return os.path.join(pueue_dir, 'shared_secret')

# ============ NETWORK CLIENT ============

def read_message(sock):
    """Read a length-prefixed message from socket"""
    header = b""
    while len(header) < 8:
        chunk = sock.recv(8 - len(header))
        if not chunk:
            raise IOError("I/O error while reading request size header:\nearly eof")
        header += chunk
    length = struct.unpack('>Q', header)[0]
    body = b""
    while len(body) < length:
        chunk = sock.recv(length - len(body))
        if not chunk:
            raise IOError("I/O error while reading message body:\nearly eof")
        body += chunk
    return body

def send_message(sock, data):
    """Send a length-prefixed message to socket"""
    if isinstance(data, str):
        data = data.encode('utf-8')
    header = struct.pack('>Q', len(data))
    sock.sendall(header + data)

def connect_to_daemon(config, socket_path, secret_path):
