            f'I/O error at path "{secret_path}" while opening secret file. Did you start the daemon at least once?:\nNo such file or directory (os error 2)'
        ])
        sys.exit(1)

    # Connect to socket
    try:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.connect(socket_path)
    except FileNotFoundError:
        error_msg_chain([
            "Failed to initialize client.",
            "Failed to initialize stream.",
            f'I/O error at path "{socket_path}" while connecting to daemon. Did you start it?:\nNo such file or directory (os error 2)'
        ])
        sys.exit(1)
    except ConnectionRefusedError:
        error_msg_chain([
            "Failed to initialize client.",
            "Failed to initialize stream.",
            f'I/O error at path "{socket_path}" while connecting to daemon. Did you start it?:\nConnection refused (os error 111)'
        ])
        sys.exit(1)
    except Exception as e:
        error_msg_chain([
            "Failed to initialize client.",
            "Failed to initialize stream.",
            str(e)
        ])
        sys.exit(1)

    # Send secret
    try:
        send_message(s, secret)
    except Exception as e:
        error_msg_chain(["Failed to initialize client.", str(e)])
        sys.exit(1)

    # Receive version
    try:
        version_bytes = read_message(s)
        version = version_bytes.decode('utf-8')
    except IOError as e:
        error_msg_chain([
            "Failed to initialize client.",
            "Failed to receive version during handshake with daemon.",
            str(e)
        ])
        sys.exit(1)

    # Check version
    if version != PROTOCOL_VERSION:
        import logging
        # Print warning to stderr in log format
        now = datetime.now().strftime('%H:%M:%S')
        if _use_color:
            sys.stderr.write(f"{Color.DIM}{now}{Color.RESET} {Color.YELLOW} WARN{Color.RESET} {Color.DIM}pueue_lib::network::client{Color.RESET}{Color.DIM}:{Color.RESET} Different protocol version detected '{version}'. Consider updating and restarting the daemon.\n")
        else:
            sys.stderr.write(f"{now}  WARN pueue_lib::network::client: Different protocol version detected '{version}'. Consider updating and restarting the daemon.\n")

    return s

def send_request(sock, request):
    """Send a CBOR-encoded request"""
    data = cbor_encode(request)
    send_message(sock, data)

def receive_response(sock):
    """Receive and decode a CBOR response"""
    try:
        data = read_message(sock)
    except IOError as e:
        raise IOError(str(e))

    try:
        response, _ = cbor_decode(data, 0)
    except Exception as e:
        error_msg_chain([f"Couldn't deserialize message:\n{e}"])
        sys.exit(1)

    return response

def get_client(config_path=None):
