# ============ OUTPUT FORMATTING ============

def format_group_status(name, group, filter_group=None):
    """Format a single group header line"""
    parallel = group.get('parallel_tasks', 1)
    status = group.get('status', 'Running').lower()
    return f'Group "{name}" ({parallel} parallel): {status}'

def format_status_output(state, filter_group=None, json_output=False):
    """Format and print status output"""
    tasks = state.get('tasks', {})
    groups = state.get('groups', {})

    if json_output:
        # Output as JSON
        # Re-serialize the state to JSON
        output = json.dumps(state, separators=(',', ':'))
        print(output)
        return

    if filter_group:
        # Show only the specified group
        if filter_group not in groups:
            print(f'Group "{filter_group}" (0 parallel): running')
            print(f'Task list is empty. Add tasks with `pueue add -g {filter_group} -- [cmd]`')
            return

        group = groups[filter_group]
        print(format_group_status(filter_group, group, filter_group))

        # Filter tasks for this group
        group_tasks = {k: v for k, v in tasks.items() 
                      if isinstance(v, dict) and v.get('group') == filter_group}

        if not group_tasks:
            print(f'Task list is empty. Add tasks with `pueue add -g {filter_group} -- [cmd]`')
        else:
            print_task_table(group_tasks, filter_group)
    else:
        # Show default group (if exists)
        if 'default' in groups:
            group = groups['default']
            print(format_group_status('default', group))
            print()

            # Filter tasks for default group
            default_tasks = {k: v for k, v in tasks.items()
                           if isinstance(v, dict) and v.get('group', 'default') == 'default'}

            if not default_tasks:
                print('Task list is empty. Add tasks with `pueue add -- [cmd]`')
            else:
                print_task_table(default_tasks, 'default')
        elif not groups:
            pass  # No groups, no output
        # If there are non-default groups but no default group, show nothing in basic mode
        # (based on testing behavior)

def print_task_table(tasks, group_name):
    """Print a formatted task table"""
    if not tasks:
        return

    # Sort tasks by id
    sorted_tasks = sorted(tasks.items(), key=lambda x: int(str(x[0])) if str(x[0]).isdigit() else 0)

    # Build table rows
    rows = []
    for task_id, task in sorted_tasks:
        if not isinstance(task, dict):
            continue
        rows.append(format_task_row(task_id, task))

