        lines = int(lines)

    # Follow output stream
    request = {'Follow': {'task_id': task_id, 'lines': lines}}
    send_request(sock, request)

    # Stream output
    try:
        while True:
            try:
                data = read_message(sock)
                response, _ = cbor_decode(data, 0)
                if isinstance(response, dict):
                    if 'Failure' in response:
                        sys.stderr.write(response['Failure'] + '\n')
                        break
                    elif 'Success' in response:
                        break
                    elif 'Stream' in response:
                        chunk = response['Stream']
                        if isinstance(chunk, bytes):
                            sys.stdout.buffer.write(chunk)
                        elif isinstance(chunk, str):
                            sys.stdout.write(chunk)
                        sys.stdout.flush()
                    elif response is None:
                        break
            except Exception:
                break
    finally:
        sock.close()

def cmd_wait(args, config, socket_path, secret_path):
    """Execute wait command"""
    quiet = getattr(args, 'quiet', False)
    status_filter = getattr(args, 'status', None)

    if getattr(args, 'all', False):
        wait_group = None
        wait_ids = None
    elif getattr(args, 'group', None):
        wait_group = args.group
        wait_ids = None
    elif getattr(args, 'task_ids', None) and args.task_ids:
        wait_ids = [int(x) for x in args.task_ids]
        wait_group = None
    else:
        wait_group = 'default'
        wait_ids = None

    # Poll status until all done
    last_status = {}

    while True:
        sock = connect_to_daemon(config, socket_path, secret_path)
        send_request(sock, "Status")
        response = receive_response(sock)
        sock.close()

        if not isinstance(response, dict) or 'Status' not in response:
            break

        state = response['Status']
        tasks = state.get('tasks', {})
        groups = state.get('groups', {})

        # Filter tasks
        if wait_ids:
            relevant = {k: v for k, v in tasks.items() if int(str(k)) in wait_ids}
            if not relevant:
                sys.stderr.write(f'No tasks found for selection TaskIds({wait_ids})\n')
                break
        elif wait_group:
            relevant = {k: v for k, v in tasks.items() 
                       if isinstance(v, dict) and v.get('group', 'default') == wait_group}
            if not relevant:
                sys.stderr.write(f'No tasks found for selection Group("{wait_group}")\n')
                break
        else:
            relevant = tasks

        # Check if all done
        all_done = True
        for task_id, task in relevant.items():
            if not isinstance(task, dict):
                continue
            status = task.get('status', '')
            if isinstance(status, str) and status in ('Queued', 'Running', 'Paused', 'Stashed', 'Locked'):
                all_done = False
                break
            elif isinstance(status, dict) and 'Done' not in status:
                all_done = False
                break

        if all_done:
            break

        if not quiet:
            # Print waiting message
            pass

        time.sleep(1)

