def cmd_reset(args, config, socket_path, secret_path):
    """Execute reset command"""
    force = getattr(args, 'force', False)
    groups_filter = getattr(args, 'groups', None)

    if not force:
        # Ask for confirmation
        show_confirmation = config.get('client', {}).get('show_confirmation_questions', False)
        if show_confirmation:
            answer = input('This will kill all running tasks and reset pueue. Continue? [Y/n] ')
            if answer.lower() not in ('', 'y', 'yes'):
                return

    # First get status to know which groups to reset
    sock = connect_to_daemon(config, socket_path, secret_path)
    send_request(sock, "Status")
    response = receive_response(sock)

    if not isinstance(response, dict) or 'Status' not in response:
        sock.close()
        return

    state = response['Status']
    all_groups = list(state.get('groups', {}).keys())

    if groups_filter:
        target_groups = [g for g in groups_filter if g in all_groups]
    else:
        target_groups = all_groups

    send_request(sock, {'Reset': {'target': {'Groups': target_groups}}})
    response = receive_response(sock)
    sock.close()
    handle_response_simple(response)

