def cmd_restart(args, config, socket_path, secret_path):
    """Execute restart command"""
    in_place = getattr(args, 'in_place', False)
    not_in_place = getattr(args, 'not_in_place', False)
    all_failed = getattr(args, 'all_failed', False)
    failed_in_group = getattr(args, 'failed_in_group', None)
    task_ids = getattr(args, 'task_ids', [])
    immediate = getattr(args, 'immediate', False)
    stashed = getattr(args, 'stashed', False)
    edit = getattr(args, 'edit', False)

    # Get current state first
    sock = connect_to_daemon(config, socket_path, secret_path)
    send_request(sock, "Status")
    response = receive_response(sock)

    if not isinstance(response, dict) or 'Status' not in response:
        sock.close()
        handle_unexpected_response(response, "pueue/src/client/commands/mod.rs", 110)
        return

    state = response['Status']
    tasks = state.get('tasks', {})

    # Determine which tasks to restart
    tasks_to_restart = []

    if all_failed:
        for task_id, task in tasks.items():
            if isinstance(task, dict):
                status = task.get('status', '')
                if isinstance(status, dict) and 'Done' in status:
                    result = status['Done']
                    if isinstance(result, dict) and 'Failed' in result:
                        tasks_to_restart.append(task)
                    elif isinstance(result, str) and result != 'Success':
                        tasks_to_restart.append(task)
    elif failed_in_group:
        for task_id, task in tasks.items():
            if isinstance(task, dict) and task.get('group') == failed_in_group:
                status = task.get('status', '')
                if isinstance(status, dict) and 'Done' in status:
                    result = status['Done']
                    if (isinstance(result, dict) and 'Failed' in result) or \
                       (isinstance(result, str) and result != 'Success'):
                        tasks_to_restart.append(task)
    else:
        for tid in task_ids:
            tid_int = int(tid)
            task = tasks.get(tid_int) or tasks.get(str(tid_int))
            if task:
                tasks_to_restart.append(task)
            else:
                sys.stderr.write(f"Couldn't restart tasks: [{tid}]\n")

    if not tasks_to_restart and not task_ids:
        sock.close()
        return

    if not tasks_to_restart and task_ids:
        failed_ids = [int(x) for x in task_ids]
        sys.stderr.write(f"Couldn't restart tasks: {failed_ids}\n")
        sock.close()
        return

    # Check restart_in_place config
    config_in_place = config.get('client', {}).get('restart_in_place', False)
    use_in_place = (in_place or config_in_place) and not not_in_place

    if use_in_place:
        # Send Restart in-place request
        task_ids_int = []
        for task in tasks_to_restart:
            if isinstance(task, dict) and 'id' in task:
                task_ids_int.append(task['id'])

        if task_ids_int:
            request = {'Restart': {
                'tasks': [{'task_id': tid, 'start_immediately': immediate, 'stashed': stashed} 
                          for tid in task_ids_int],
                'in_place': True,
            }}
            send_request(sock, request)
            response = receive_response(sock)
            sock.close()
            handle_response_simple(response)
        else:
            sock.close()
        return

    # Create new tasks (not in-place) by sending Add requests
    all_responses = []
    for task in tasks_to_restart:
        if not isinstance(task, dict):
            continue

        add_request = {
            'Add': {
                'command': task.get('command', task.get('original_command', '')),
                'path': task.get('path', os.getcwd()),
                'envs': task.get('envs', {}),
                'start_immediately': immediate,
                'stashed': stashed,
                'group': task.get('group', 'default'),
                'enqueue_at': None,
                'dependencies': task.get('dependencies', []),
                'priority': task.get('priority', None),
                'label': task.get('label', None),
            }
        }
        send_request(sock, add_request)
        resp = receive_response(sock)
        all_responses.append(resp)

    sock.close()

    for resp in all_responses:
        handle_response_simple(resp)

