def handle_response_simple(response, socket_conn=None):
    """Handle a Success/Failure response"""
    if socket_conn:
        socket_conn.close()

    if isinstance(response, dict):
        if 'Success' in response:
            msg = response['Success']
            if msg:
                print(msg)
            else:
                print()
        elif 'Failure' in response:
            msg = response['Failure']
            sys.stderr.write(msg + '\n')
        elif 'Status' in response:
            # Unexpected for simple commands but handle gracefully
            pass
        else:
            # Unknown response - just silently ignore or log
            import sys
            now = datetime.now().strftime('%H:%M:%S')
            if _use_color:
                sys.stderr.write(f"{Color.DIM}{now}{Color.RESET} {Color.RED}ERROR{Color.RESET} {Color.DIM}pueue::client::commands{Color.RESET}{Color.DIM}:{Color.RESET} Received unhandled response message\n")
            else:
                sys.stderr.write(f"{now} ERROR pueue::client::commands: Received unhandled response message\n")
    elif isinstance(response, str):
        print(response)

