def handle_unexpected_response(response, location, line):
    """Handle unexpected response"""
    # Format the value like ciborium's debug output
    formatted = format_cbor_value(response)
    if _use_color:
        sys.stderr.write(f"Error: \n   0: {Color.RED}Got unexpected but valid message. Are you up-to-date?:\n      {formatted}{Color.RESET}\n\n")
    else:
        sys.stderr.write(f"Error: \n   0: Got unexpected but valid message. Are you up-to-date?:\n      {formatted}\n\n")
    sys.stderr.write(f"\nLocation:\n")
    if _use_color:
        sys.stderr.write(f"   {Color.MAGENTA}{location}{Color.RESET}:{Color.MAGENTA}{line}{Color.RESET}\n\n")
    else:
        sys.stderr.write(f"   {location}:{line}\n\n")
    sys.stderr.write("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n")
    sys.stderr.write("Run with RUST_BACKTRACE=full to include source snippets.\n")
    sys.exit(1)

def format_cbor_value(val, indent=0):
    """Format a value like ciborium's debug output"""
    spaces = "    " * indent
    if val is None:
        return "Null"
    elif isinstance(val, bool):
        return "True" if val else "False"
    elif isinstance(val, int):
        return f"Integer(\n{spaces}    Integer(\n{spaces}        {val},\n{spaces}    ),\n{spaces})"
    elif isinstance(val, float):
        return f"Float(\n{spaces}    {val},\n{spaces})"
    elif isinstance(val, str):
        return f"Text(\n{spaces}    \"{val}\",\n{spaces})"
    elif isinstance(val, bytes):
        return f"Bytes(\n{spaces}    {val!r},\n{spaces})"
    elif isinstance(val, list):
        items = ',\n'.join(f"{spaces}    {format_cbor_value(x, indent+1)}" for x in val)
        return f"Array(\n{spaces}    [\n{items}\n{spaces}    ],\n{spaces})"
    elif isinstance(val, dict):
        pairs = []
        for k, v in val.items():
            kf = format_cbor_value(k, indent+2)
            vf = format_cbor_value(v, indent+2)
            pairs.append(f"{spaces}        (\n{spaces}            {kf},\n{spaces}            {vf},\n{spaces}        )")
        items_str = ',\n'.join(pairs)
        return f"Map(\n{spaces}    [\n{items_str},\n{spaces}    ],\n{spaces})"
    return str(val)

