def parse_delay(delay_str):
    """Parse a delay string to RFC3339 datetime"""
    import re
    from datetime import datetime, timezone, timedelta

    now = datetime.now(timezone.utc)

    # Try as seconds
    try:
        secs = float(delay_str)
        dt = now + timedelta(seconds=secs)
        return dt.strftime('%Y-%m-%dT%H:%M:%S.%f') + '000Z'
    except ValueError:
        pass

    # Try RFC3339/ISO8601
    try:
        if 'T' in delay_str:
            dt = datetime.fromisoformat(delay_str.replace('Z', '+00:00'))
            return dt.strftime('%Y-%m-%dT%H:%M:%S.%f') + '000Z'
    except ValueError:
        pass

    # Try relative like "3h", "2d", "1w", "4 months"
    patterns = [
        (r'^(\d+)\s*s(?:ec(?:onds?)?)?$', 'seconds'),
        (r'^(\d+)\s*m(?:in(?:utes?)?)?$', 'minutes'),
        (r'^(\d+)\s*h(?:ours?)?$', 'hours'),
        (r'^(\d+)\s*d(?:ays?)?$', 'days'),
        (r'^(\d+)\s*w(?:eeks?)?$', 'weeks'),
        (r'^(\d+)\s*months?$', 'months'),
    ]

    for pattern, unit in patterns:
        m = re.match(pattern, delay_str.strip(), re.IGNORECASE)
        if m:
            n = int(m.group(1))
            if unit == 'seconds':
                dt = now + timedelta(seconds=n)
            elif unit == 'minutes':
                dt = now + timedelta(minutes=n)
            elif unit == 'hours':
                dt = now + timedelta(hours=n)
            elif unit == 'days':
                dt = now + timedelta(days=n)
            elif unit == 'weeks':
                dt = now + timedelta(weeks=n)
            elif unit == 'months':
                dt = now + timedelta(days=n*30)
            return dt.strftime('%Y-%m-%dT%H:%M:%S.%f') + '000Z'

    # Just return current time + 0
    return now.strftime('%Y-%m-%dT%H:%M:%S.%f') + '000Z'

