def cmd_wait(args, config, socket_path, secret_path):
    """Execute wait command"""
    quiet = getattr(args, 'quiet', False)
    status_filter = getattr(args, 'status', None)

    if getattr(args, 'all', False):
        wait_group = None
        wait_ids = None
    elif getattr(args, 'group', None):
        wait_group = args.group
        wait_ids = None
    elif getattr(args, 'task_ids', None) and args.task_ids:
        wait_ids = [int(x) for x in args.task_ids]
        wait_group = None
    else:
        wait_group = 'default'
        wait_ids = None

    # Poll status until all done
    last_status = {}

    while True:
        sock = connect_to_daemon(config, socket_path, secret_path)
        send_request(sock, "Status")
        response = receive_response(sock)
        sock.close()

        if not isinstance(response, dict) or 'Status' not in response:
            break

        state = response['Status']
        tasks = state.get('tasks', {})
        groups = state.get('groups', {})

        # Filter tasks
        if wait_ids:
            relevant = {k: v for k, v in tasks.items() if int(str(k)) in wait_ids}
            if not relevant:
                sys.stderr.write(f'No tasks found for selection TaskIds({wait_ids})\n')
                break
        elif wait_group:
            relevant = {k: v for k, v in tasks.items() 
                       if isinstance(v, dict) and v.get('group', 'default') == wait_group}
            if not relevant:
                sys.stderr.write(f'No tasks found for selection Group("{wait_group}")\n')
                break
        else:
            relevant = tasks

        # Check if all done
        all_done = True
        for task_id, task in relevant.items():
            if not isinstance(task, dict):
                continue
            status = task.get('status', '')
            if isinstance(status, str) and status in ('Queued', 'Running', 'Paused', 'Stashed', 'Locked'):
                all_done = False
                break
            elif isinstance(status, dict) and 'Done' not in status:
                all_done = False
                break

        if all_done:
            break

        if not quiet:
            # Print waiting message
            pass

        time.sleep(1)

def cmd_clean(args, config, socket_path, secret_path):
    """Execute clean command"""
    sock = connect_to_daemon(config, socket_path, secret_path)
    send_request(sock, {'Clean': {
        'successful_only': getattr(args, 'successful_only', False),
        'group': getattr(args, 'group', None),
    }})
    response = receive_response(sock)
    sock.close()
    handle_response_simple(response)

def cmd_reset(args, config, socket_path, secret_path):
    """Execute reset command"""
    force = getattr(args, 'force', False)
    groups_filter = getattr(args, 'groups', None)

    if not force:
        # Ask for confirmation
        show_confirmation = config.get('client', {}).get('show_confirmation_questions', False)
        if show_confirmation:
            answer = input('This will kill all running tasks and reset pueue. Continue? [Y/n] ')
            if answer.lower() not in ('', 'y', 'yes'):
                return

    # First get status to know which groups to reset
    sock = connect_to_daemon(config, socket_path, secret_path)
    send_request(sock, "Status")
    response = receive_response(sock)

    if not isinstance(response, dict) or 'Status' not in response:
        sock.close()
        return

    state = response['Status']
    all_groups = list(state.get('groups', {}).keys())

    if groups_filter:
        target_groups = [g for g in groups_filter if g in all_groups]
    else:
        target_groups = all_groups

    send_request(sock, {'Reset': {'target': {'Groups': target_groups}}})
    response = receive_response(sock)
    sock.close()
    handle_response_simple(response)

