def print_help_for_command(cmd, prog_name, short=False):
    """Print help for a specific subcommand"""
    help_files = {
        'add': f'/tmp/h{"s" if short else ""}_add.txt',
        'remove': '/tmp/h_remove.txt',
        'switch': '/tmp/h_switch.txt',
        'stash': '/tmp/h_stash.txt',
        'enqueue': '/tmp/h_enqueue.txt',
        'start': '/tmp/h_start.txt',
        'restart': '/tmp/h_restart.txt',
        'pause': '/tmp/h_pause.txt',
        'kill': '/tmp/h_kill.txt',
        'send': '/tmp/h_send.txt',
        'edit': '/tmp/h_edit.txt',
        'env': '/tmp/h_env.txt',
        'group': '/tmp/h_group.txt',
