        'log': '/tmp/h_log.txt',
        'follow': '/tmp/h_follow.txt',
        'wait': '/tmp/h_wait.txt',
        'clean': '/tmp/h_clean.txt',
        'reset': '/tmp/h_reset.txt',
        'shutdown': '/tmp/h_shutdown.txt',
        'parallel': '/tmp/h_parallel.txt',
        'completions': '/tmp/h_completions.txt',
    }

    # Try to read from bundled help files
    script_dir = os.path.dirname(os.path.realpath(__file__))
    help_dir = os.path.join(script_dir, 'help')

    if cmd in help_files:
        # Try bundled help first
        bundled = os.path.join(help_dir, os.path.basename(help_files[cmd]))
        if os.path.exists(bundled):
            with open(bundled) as f:
                text = f.read()
            text = text.replace('executable', prog_name)
            print(text, end='')
            return
        # Fall back to temp files (for testing)
        if os.path.exists(help_files[cmd]):
            with open(help_files[cmd]) as f:
                text = f.read()
            text = text.replace('executable', prog_name)
            print(text, end='')
            return

    # Default: generate simple help
    print(f"Help for {cmd} not available")

