        'shutdown': '/tmp/h_shutdown.txt',
        'parallel': '/tmp/h_parallel.txt',
        'completions': '/tmp/h_completions.txt',
    }

    # Try to read from bundled help files
    script_dir = os.path.dirname(os.path.realpath(__file__))
