def main():
    global _use_color

    prog_name = os.path.basename(sys.argv[0])

    # Pre-parse to handle --color and early exits
    args_raw = sys.argv[1:]

    # Handle color setting
    color_setting = 'auto'
    for i, arg in enumerate(args_raw):
        if arg == '--color' and i + 1 < len(args_raw):
            color_setting = args_raw[i + 1]
        elif arg.startswith('--color='):
            color_setting = arg.split('=', 1)[1]

    if color_setting == 'never':
        _use_color = False
    elif color_setting == 'always':
        _use_color = True
    else:  # auto
        _use_color = sys.stdout.isatty()

    # Handle --version
    if '-V' in args_raw or '--version' in args_raw:
        print(f"pueue {VERSION}")
        return

    # Handle no args or --help/-h
    if not args_raw or args_raw == ['-h']:
        print_main_help(short=True)
        return

    if args_raw == ['--help']:
        print_main_help(short=False)
        return

    # Check for subcommand
    subcommands = ['add', 'remove', 'switch', 'stash', 'enqueue', 'start', 'restart',
                   'pause', 'kill', 'send', 'edit', 'env', 'group', 'status', 'log',
                   'follow', 'wait', 'clean', 'reset', 'shutdown', 'parallel', 'completions', 'help']

    # Find the subcommand
    config_path = None
    cmd = None
    i = 0
    remaining = []

    while i < len(args_raw):
        arg = args_raw[i]
        if arg in ('-c', '--config'):
            if i + 1 < len(args_raw):
                config_path = args_raw[i + 1]
                i += 2
            else:
                i += 1
        elif arg.startswith('--config='):
            config_path = arg.split('=', 1)[1]
            i += 1
        elif arg in ('-v', '--verbose', '-vv', '-vvv'):
            i += 1
        elif arg in ('--color',):
            i += 2  # skip value too
        elif arg.startswith('--color='):
            i += 1
        elif arg in ('-p', '--profile'):
            i += 2  # skip profile value
        elif arg.startswith('--profile='):
            i += 1
        elif arg in subcommands:
            cmd = arg
            remaining = args_raw[i+1:]
            break
        elif arg in ('-V', '--version', '-h', '--help'):
            i += 1
        else:
            # Unknown option
            sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n")
            sys.stderr.write(f"Usage: {prog_name} [OPTIONS] [COMMAND]\n\n")
            sys.stderr.write(f"For more information, try '--help'.\n")
            sys.exit(2)

    if cmd is None:
        print_main_help(short=True)
        return

    # Handle 'help' command
    if cmd == 'help':
        if remaining:
            subcmd = remaining[0]
            print_help_for_command(subcmd, prog_name, short=False)
        else:
            print_main_help(short=False)
        return

    # Handle --help/-h for subcommands
    if '-h' in remaining:
        print_help_for_command(cmd, prog_name, short=True)
        return
    if '--help' in remaining:
        print_help_for_command(cmd, prog_name, short=False)
        return

    # Handle completions (doesn't need daemon)
    if cmd == 'completions':
        # Parse completions args
        if not remaining:
            sys.stderr.write(f"error: the following required arguments were not provided:\n")
            sys.stderr.write(f"  <SHELL>\n\n")
            sys.stderr.write(f"Usage: {prog_name} completions <SHELL> [OUTPUT_DIRECTORY]\n\n")
            sys.stderr.write(f"For more information, try '--help'.\n")
            sys.exit(2)

        shell = remaining[0]
        valid_shells = ['bash', 'elvish', 'fish', 'power-shell', 'zsh', 'nushell']
        if shell not in valid_shells:
            print_error_invalid_value(shell, '<SHELL>', valid_shells)
            sys.exit(2)

        class CompArgs:
            pass
        comp_args = CompArgs()
        comp_args.shell = shell
        comp_args.output_directory = remaining[1] if len(remaining) > 1 else None
        cmd_completions(comp_args)
        return

    # Get config and connect for all other commands
    config, socket_path, secret_path = get_client(config_path)

    # Parse command-specific arguments
    try:
        _dispatch_command(cmd, remaining, config, socket_path, secret_path, prog_name)
    except SystemExit:
        raise
    except KeyboardInterrupt:
        sys.exit(130)

