    def read_uint(additional):
        nonlocal pos
        if additional < 24: return additional
        elif additional == 24: v = data[pos]; pos += 1; return v
        elif additional == 25: v = int.from_bytes(data[pos:pos+2], 'big'); pos += 2; return v
        elif additional == 26: v = int.from_bytes(data[pos:pos+4], 'big'); pos += 4; return v
        elif additional == 27: v = int.from_bytes(data[pos:pos+8], 'big'); pos += 8; return v
    def decode():
        nonlocal pos
        b = data[pos]; pos += 1
        major = b >> 5; additional = b & 0x1f
